package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierTable struct {
	TierEntry struct {
		TierLimit decimal.Decimal
		TierRate  decimal.Decimal
	}
}

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var SrId string
var SrSales decimal.Decimal = decimal.NewFromInt(0)

var tierLimits [5]decimal.Decimal
var tierRates [5]decimal.Decimal

var salesLines []string
var salesPos int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func formatWithPattern(v decimal.Decimal, intPat string, fracDigits int) string {
	var slotTypes []byte
	for i := 0; i < len(intPat); i++ {
		c := intPat[i]
		if c == 'Z' || c == '9' {
			slotTypes = append(slotTypes, c)
		}
	}
	intDigits := len(slotTypes)
	av := v.Abs()
	q := av.Shift(int32(fracDigits)).Truncate(0)
	intVal := q.IntPart()
	powFrac := pow10(fracDigits)
	var fracPart int64
	var intPartFull int64
	if fracDigits == 0 {
		fracPart = 0
		intPartFull = intVal
	} else {
		fracPart = intVal % powFrac
		if fracPart < 0 {
			fracPart = -fracPart
		}
		intPartFull = intVal / powFrac
	}
	powInt := pow10(intDigits)
	intPartLow := intPartFull % powInt
	if intPartLow < 0 {
		intPartLow = -intPartLow
	}
	digits := fmt.Sprintf("%0*d", intDigits, intPartLow)
	var intOut []byte
	slotIdx := 0
	stillSupp := true
	for i := 0; i < len(intPat); i++ {
		c := intPat[i]
		if c == ',' {
			if stillSupp {
				intOut = append(intOut, ' ')
			} else {
				intOut = append(intOut, ',')
			}
		} else {
			d := digits[slotIdx]
			if c == '9' {
				intOut = append(intOut, d)
				stillSupp = false
			} else {
				if stillSupp && d == '0' {
					intOut = append(intOut, ' ')
				} else {
					intOut = append(intOut, d)
					if d != '0' {
						stillSupp = false
					} else {
						if !stillSupp {
						}
					}
					if stillSupp && d != '0' {
						stillSupp = false
					} else if !stillSupp {
					}
					// if digit non-zero, stop suppression; if already not suppressed keep it
					if d != '0' {
						stillSupp = false
					} else {
						// d == '0' but we already output '0' because not suppressed
					}
				}
				// Correct stillSupp handling: if we output a real digit (non-space), clear flag
				// Re-evaluate: if intOut last char != ' ' then not suppressed anymore
				// Simpler: if d != '0' then stillSupp=false, else if !stillSupp keep false
				// The above already does; ensure flag cleared when non-zero seen
				if d != '0' {
					stillSupp = false
				} else {
					// if we printed '0' (not space), then we are no longer suppressed
					if len(intOut) > 0 && intOut[len(intOut)-1] == '0' {
						stillSupp = false
					}
				}
			}
			slotIdx++
		}
	}
	fracStr := ""
	if fracDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracPart)
		return string(intOut) + "." + fracStr
	}
	return string(intOut)
}

func wrapComm(v decimal.Decimal) decimal.Decimal {
	scaled := v.Shift(2).Truncate(0).IntPart()
	const mod int64 = 100000000
	r := scaled % mod
	return decimal.New(r, -2)
}

func wrapTotal(v decimal.Decimal) decimal.Decimal {
	scaled := v.Shift(2).Truncate(0).IntPart()
	const mod int64 = 100000000000
	r := scaled % mod
	return decimal.New(r, -2)
}

func MainPara() {
	InitPara()
	// OPEN INPUT SALES-FILE
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			salesLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		s := string(data)
		if len(data) == 0 {
			salesLines = nil
		} else {
			parts := strings.Split(s, "\n")
			if strings.HasSuffix(s, "\n") {
				parts = parts[:len(parts)-1]
			}
			for i, p := range parts {
				if len(p) > 0 && p[len(p)-1] == '\r' {
					parts[i] = p[:len(p)-1]
				}
			}
			salesLines = parts
		}
	}
	salesPos = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE SALES-FILE (no-op)
	SummaryPara()
}

func InitPara() {
	tierLimits[1] = decimal.New(100000, -2)
	tierRates[1] = decimal.New(250, -2)
	tierLimits[2] = decimal.New(500000, -2)
	tierRates[2] = decimal.New(400, -2)
	tierLimits[3] = decimal.New(2000000, -2)
	tierRates[3] = decimal.New(550, -2)
	tierLimits[4] = decimal.New(99999999, -2)
	tierRates[4] = decimal.New(725, -2)
}

func ReadPara() {
	if salesPos >= len(salesLines) {
		WsEofFlag = "Y"
		return
	}
	line := salesLines[salesPos]
	salesPos++
	if len(line) < 12 {
		line += strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	SrId = line[0:4]
	salesStr := line[4:12]
	var n int64 = 0
	for i := 0; i < 8; i++ {
		c := salesStr[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else {
			d = 0
		}
		n = n*10 + d
	}
	SrSales = decimal.New(n, -2)
}

func ProcessPara() {
	WsTier = 0
	// PERFORM VARYING WS-IDX FROM 1 BY 1 UNTIL WS-IDX > 4 OR WS-TIER > 0
	WsIdx = 1
	for !(WsIdx > 4 || WsTier > 0) {
		if SrSales.Cmp(tierLimits[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
		WsIdx += 1
	}
	tmp := SrSales.Mul(tierRates[WsTier]).Shift(-2)
	rounded := tmp.Round(2)
	WsComm = wrapComm(rounded)
	WsTotal = wrapTotal(WsTotal.Add(WsComm))
	WsCount = (WsCount + 1) % 1000
	WsSalesEd = formatWithPattern(SrSales, "ZZZ,ZZ9", 2)
	WsRateEd = formatWithPattern(tierRates[WsTier], "9", 2)
	WsCommEd = formatWithPattern(WsComm, "ZZZ,ZZ9", 2)
	tierStr := fmt.Sprintf("%d", WsTier)
	line := SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	os.Stdout.WriteString(line + "\n")
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatWithPattern(WsTotal, "ZZZ,ZZZ,ZZ9", 2)
	countStr := fmt.Sprintf("%03d", WsCount)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	os.Stdout.WriteString(line + "\n")
}

func main() {
	MainPara()
}
